using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class C02RefineApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B5/",P=A+"Props/B5/";
 static Dictionary<string,Material> mats;static Transform parent;static List<object> placements;
 static void ImportModel(string path){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var m in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.Key),m.Value);mi.SaveAndReimport();}
 static void Model(string n,Vector3 p,float yaw,Vector3 size=default(Vector3),Vector3 center=default(Vector3),bool env=false){var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((env?E:P)+n+".fbx"),parent);go.name=n;go.transform.localPosition=p;go.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var r in go.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>mats[m.name]).ToArray();if(size!=Vector3.zero){var c=go.AddComponent<BoxCollider>();c.size=size;c.center=center;}placements.Add(new{model=n,p=new[]{p.x,p.y,p.z},yaw,colliderSize=new[]{size.x,size.y,size.z}});}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("C02_Security_Art");if(!group)throw new Exception("Current C02 body missing");var project=Path.GetFullPath(Path.Combine(Application.dataPath,".."));var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 foreach(var tex in new[]{"SC_Display_05","SR_EquipmentPrint"}){var path=P+"Textures/"+tex+".png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.maxTextureSize=2048;ti.mipmapEnabled=true;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=TextureWrapMode.Clamp;ti.SaveAndReimport();}
 var labelPath=P+"Materials/SC_EquipmentPrint.mat";var label=AssetDatabase.LoadAssetAtPath<Material>(labelPath);if(!label){label=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(label,labelPath);}label.name="SC_EquipmentPrint";label.SetColor("_BaseColor",Color.white);label.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/SR_EquipmentPrint.png"));label.SetFloat("_Smoothness",.25f);label.SetFloat("_Metallic",.1f);EditorUtility.SetDirty(label);AssetDatabase.SaveAssetIfDirty(label);
 mats=Directory.GetFiles(Path.Combine(project,P,"Materials"),"SC_*.mat").Select(f=>AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+Path.GetFileName(f))).ToDictionary(m=>m.name);
 foreach(string name in new[]{"SC_OperatorDesk_A","SC_OperatorDesk_B","SC_VideoWall","SC_IncidentReview","SC_RadioDutyStation","SC_NetworkRack","SC_RecorderRack","SC_UPSRack"})ImportModel(P+name+".fbx");
 foreach(string folder in new[]{P,E})foreach(var f in Directory.GetFiles(Path.Combine(project,folder),"SR_*.fbx"))ImportModel(folder+Path.GetFileName(f));
 var old=group.Find("C02_Equipment_Infill");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var g=new GameObject("C02_Equipment_Infill");g.transform.SetParent(group,false);parent=g.transform;placements=new List<object>();Undo.RegisterCreatedObjectUndo(g,"C02 equipment and monitor refinement");
 Model("SR_AVServiceRack",new Vector3(-3.85f,0,4.65f),140.4f,new Vector3(1.04f,2.06f,.96f),new Vector3(0,1.03f,.14f));
 Model("SR_CredentialStation",new Vector3(-5.95f,0,-.30f),88,new Vector3(1.06f,2.07f,.71f),new Vector3(0,1.035f,.145f));
 Model("SR_EvidenceCabinet",new Vector3(4.3f,0,-4.37f),314.3f,new Vector3(1.30f,2.05f,.72f),new Vector3(0,1.025f,.035f));
 Model("SR_ShiftEquipment",new Vector3(-5.23f,0,-3.76f),54.25f,new Vector3(1.60f,1.22f,.55f),new Vector3(0,1.64f,.15f));
 Model("SR_NorthAirReturn",Vector3.zero,0,env:true);Model("SR_WallServices",Vector3.zero,0,env:true);
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{scene=s.path,newModels=placements,upgradedModels=8,renderers=group.GetComponentsInChildren<Renderer>().Length,colliders=group.GetComponentsInChildren<Collider>().Length,lights=root.GetComponentsInChildren<Light>(true).Length};File.WriteAllText(repo+"/Docs/검수/2026-11-08_C02_Refine/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
}
